packagegui.custom_php_global_functions:

function flexiwan_validate_config($post, &$input_errors) {
    // Validate backend URL
    if (!empty($post['backend_url'])) {
        if (!filter_var($post['backend_url'], FILTER_VALIDATE_URL)) {
            $input_errors[] = 'Invalid backend URL format';
        }
    }

    // Validate sync interval
    if (!empty($post['sync_interval'])) {
        if (!is_numeric($post['sync_interval']) || $post['sync_interval'] < 10) {
            $input_errors[] = 'Sync interval must be a number >= 10 seconds';
        }
    }

    // Validate health report interval
    if (!empty($post['health_report_interval'])) {
        if (!is_numeric($post['health_report_interval']) || $post['health_report_interval'] < 10) {
            $input_errors[] = 'Health report interval must be a number >= 10 seconds';
        }
    }

    return $input_errors;
}

packagegui.custom_php_install_command:

// Create log file
@touch('/var/log/flexiwan.log');
@chmod('/var/log/flexiwan.log', 0644);

// Create cache directory
@mkdir('/var/cache/flexiwan', 0755, true);

// Initialize configuration if not present
require_once('/usr/local/pkg/flexiwan.inc');
if (!isset($config['installedpackages']['flexiwan'])) {
    $config['installedpackages']['flexiwan'] = array(
        'enabled' => false,
        'backend_url' => 'https://manage.flexiwan.com',
        'sync_interval' => 300,
        'health_report_interval' => 60,
        'debug_logging' => false
    );
    write_config('FlexiWAN configuration initialized');
}

packagegui.custom_php_deinstall_command:

// Stop the service
mwexec('/usr/local/etc/rc.d/flexiwan.sh stop', true);

// Remove log file
@unlink('/var/log/flexiwan.log');

// Remove cache directory
@exec('rm -rf /var/cache/flexiwan');

// Clear configuration
if (isset($config['installedpackages']['flexiwan'])) {
    unset($config['installedpackages']['flexiwan']);
    write_config('FlexiWAN configuration removed');
}

packagegui.custom_php_service_status_command:

$status = array();
if (isset($config['installedpackages']['flexiwan']) && 
    $config['installedpackages']['flexiwan']['enabled']) {
    $status['enabled'] = true;
    $status['running'] = is_process_running('flexiwand');
} else {
    $status['enabled'] = false;
    $status['running'] = false;
}
return $status;
